import{_ as s,o as t,a as n,b as p}from"./app.C41L12d5.js";const d="/ascendc.github.io/assets/constant_padding_mode.Dul9JksK.png",l="/ascendc.github.io/assets/row_col_padding_mode.B9diJfN0.png",c="/ascendc.github.io/assets/block_padding_mode.D6CwDZQD.png",i="/ascendc.github.io/assets/mirror_block_padding_mode.CFV5RJFD.png",r="/ascendc.github.io/assets/zh-cn_formulaimage_0000001938335310.CiABFIKx.png",e="/ascendc.github.io/assets/zh-cn_formulaimage_0000001938176178.CPU0pjGq.png",v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬入辅助配置接口","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/cube_load_aux_config"},{"text":"SetAippFunctions","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetAippFunctions"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetAippFunctions.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetAippFunctions.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),o={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/SetAippFunctions.md"};function h(b,a,g,u,m,_){return t(),n("div",null,[...a[0]||(a[0]=[p('<div><article class="markdown-body"><h1>SetAippFunctions<span id="ZH-CN_TOPIC_0000001913015092"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>设置图片预处理（AIPP，AI Core pre-process）相关参数。和<a href="LoadImageToLocal.html">LoadImageToLocal</a>接口配合使用。设置后，调用<a href="LoadImageToLocal.html">LoadImageToLocal</a>接口可在搬运过程中完成图像预处理操作：包括数据填充、通道交换、单行读取、数据类型转换、通道填充、色域转换。调用SetAippFunctions接口时需传入源图片在Global Memory上的矩阵、源图片的图片格式。</p><ul><li><p><strong>数据填充：</strong> 在图片HW方向上padding。分为如下几种模式：</p><ul><li><p>模式0：常量填充模式，padding区域各位置填充为常数，支持设置每个通道填充的常数。该模式下仅支持左右padding，不支持上下padding。</p><p><strong>图1</strong> 常量填充模式（图片中间的绿色区域表示原始数据，其他为padding数据）<span id="fig56681157121916"></span></p><p><img src="'+d+'" alt title="常量填充模式（图片中间的绿色区域表示原始数据——其他为padding数据）"></p></li><li><p>模式1：行列填充模式，padding区域各位置填充行/列上最邻近源图片位置的数据。</p><p><strong>图2</strong> 行列填充模式（图片中间的绿色区域表示原始数据，其他为padding数据）<span id="fig4239143712713"></span></p><p><img src="'+l+'" alt title="行列填充模式（图片中间的绿色区域表示原始数据——其他为padding数据）"></p></li><li><p>模式2：块填充模式，按照padding的宽高，从源图片拷贝数据块进行padding区域填充。</p><p><strong>图3</strong> 块填充模式（图片中间的绿色区域表示原始数据，其他为padding数据）<span id="fig38821202817"></span></p><p><img src="'+c+'" alt title="块填充模式（图片中间的绿色区域表示原始数据——其他为padding数据）"></p></li><li><p>模式3：镜像块填充模式，按照padding的宽高，从源图片拷贝数据块的镜像进行padding区域填充。</p><p><strong>图4</strong> 镜像块填充模式（图片中间的绿色区域表示原始数据，其他为padding数据）<span id="fig14371141920261"></span></p><p><img src="'+i+`" alt title="镜像块填充模式（图片中间的绿色区域表示原始数据——其他为padding数据）"></p></li></ul></li><li><p><strong>通道交换：</strong> 将图片通道进行交换。</p><ul><li>对于RGB888格式，支持交换R和B通道。</li><li>对于YUV420SP格式，支持交换U和V通道。</li><li>对于XRGB8888格式，支持X通道后移（XRGB→RGBX）和交换R和B通道。</li></ul></li><li><p><strong>单行读取：</strong> 源图片中仅读取一行。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>调用数据搬运接口时，若开启了单行读取，设置的目的图片高度参数将无效，如<a href="LoadImageToLocal.html">LoadImageToLocal</a>接口的loadImageToLocalParams.vertSize。</p></div></li><li><p><strong>数据类型转换：</strong> 转换像素的数据类型，支持uint8_t转换为int8_t或half。当uint8_t转换成int8_t的时候，输出数据范围限制在[-128，127]。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 例1：实现uint8_t -&gt;int8_t的类型转换，同时实现零均值化：设置每个通道mean值为该通道所有数据的平均值（min和var值无效，不用设置）。</span>
<span class="n">output</span><span class="p">[</span><span class="n">i</span><span class="p">][</span><span class="n">j</span><span class="p">][</span><span class="n">k</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">i</span><span class="p">][</span><span class="n">j</span><span class="p">][</span><span class="n">k</span><span class="p">]</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">mean</span><span class="p">[</span><span class="n">k</span><span class="p">]</span>
<span class="c1">// 例2：实现uint8_t -&gt; fp16的类型转换，同时实现归一化：设置每个通道mean值为该通道所有数据的平均值，min值为该通道所有数据零均值化后的最小值，var值为该通道所有数据的最大值减最小值的倒数。</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="o">-&gt;</span><span class="w"> </span><span class="n">fp16</span><span class="o">:</span><span class="w">  </span><span class="n">output</span><span class="p">[</span><span class="n">i</span><span class="p">][</span><span class="n">j</span><span class="p">][</span><span class="n">k</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">input</span><span class="p">[</span><span class="n">i</span><span class="p">][</span><span class="n">j</span><span class="p">][</span><span class="n">k</span><span class="p">]</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">mean</span><span class="p">[</span><span class="n">k</span><span class="p">]</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">min</span><span class="p">[</span><span class="n">k</span><span class="p">])</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">var</span><span class="p">[</span><span class="n">k</span><span class="p">]</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>转换后的数据类型由模板参数U决定，U为uint8_t时数据类型转换功能不生效。 调用数据搬运接口时，目的Tensor的数据类型需要与本接口输出数据类型保持一致，如<a href="LoadImageToLocal.html">LoadImageToLocal</a>的dstLocal参数的数据类型。</p></div></li><li><p><strong>通道填充：</strong> 在图片通道方向上padding。默认为模式0。</p><ul><li><p>模式0：将通道padding至32Bytes。即输出数据类型为uint8_t/int8_t时，padding至32通道；输出数据类型为fp16时，padding至16通道。</p></li><li><p>模式1：将通道padding至4通道。</p></li></ul></li><li><p><strong>色域转换：</strong> RGB格式转换为YUV格式，或YUV格式转换为RGB格式。</p><p><img src="`+r+'" alt></p><p><img src="'+e+`" alt></p></li></ul><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>输入图片格式为YUV400、RGB888、XRGB8888</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetAippFunctions</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="n">AippInputFormat</span><span class="w"> </span><span class="n">format</span><span class="p">,</span><span class="w"> </span><span class="n">AippParams</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;</span><span class="w"> </span><span class="n">config</span><span class="p">)</span>
</code></pre></div></li><li><p>输入图片格式为YUV420 Semi-Planar</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">SetAippFunctions</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="n">AippInputFormat</span><span class="w"> </span><span class="n">format</span><span class="p">,</span><span class="w"> </span><span class="n">AippParams</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;</span><span class="w"> </span><span class="n">config</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>输入的数据类型，需要与format中设置的数据类型保持一致。</td></tr><tr><td>U</td><td>输出的数据类型，需要在搬运接口配置同样的数据类型，如<a href="LoadImageToLocal.html">LoadImageToLocal</a>的dstLocal参数数据类型。<br>    •如果不使能数据类型转换功能，需要与输入类型保持一致；<br>    •如果使能数据类型转换功能，需要与期望转换后的类型保持一致。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>src0</td><td>输入</td><td>源图片在Global Memory上的矩阵。<br>源图片格式为YUV420SP时，表示Y维度在Global Memory上的矩阵。</td></tr><tr><td>src1</td><td>输入</td><td>源图片格式为YUV420SP时，表示UV维度在Global Memory上的矩阵。<br>源图片格式为其他格式时，该参数无效。</td></tr><tr><td>format</td><td>输入</td><td>源图片的图片格式。AippInputFormat为枚举类型，取值为：<br>AippInputFormat::YUV420SP_U8：图片格式为YUV420 Semi-Planar，数据类型为uint8_t<br>AippInputFormat::XRGB8888_U8：图片格式为XRGB8888，数据类型为uint8_t<br>AippInputFormat::RGB888_U8：图片格式为RGB888，数据类型为uint8_t<br>AippInputFormat::YUV400_U8：图片格式为YUV400，数据类型为uint8_t<br>enum class AippInputFormat : uint8_t {<br> YUV420SP_U8 = 0,<br> XRGB8888_U8 = 1,<br> RGB888_U8 = 4,<br> YUV400_U8 = 9,<br>};</td></tr><tr><td>config</td><td>输入</td><td>图片预处理的相关参数，类型为AippParams，结构体具体定义为：<br>template &lt;typename T&gt;<br>struct AippParams {<br> AippPaddingParams&lt;T&gt; paddingParams;<br> AippSwapParams swapParams;<br> AippSingleLineParams singleLineParams;<br> AippDataTypeConvParams dtcParams;<br> AippChannelPaddingParams&lt;T&gt; cPaddingParams;<br> AippColorSpaceConvParams cscParams;<br>};<br>AippParams结构体内各子结构体定义如下：<br>  •数据填充功能相关参数，说明见表3。<br>template &lt;typename T&gt;<br>struct AippPaddingParams {<br> uint32_t paddingMode;<br> T paddingValueCh0;<br> T paddingValueCh1;<br> T paddingValueCh2;<br> T paddingValueCh3;<br>};<br>  •通道交换功能相关参数，说明见表4。<br>struct AippSwapParams {<br> bool isSwapRB;<br> bool isSwapUV;<br> bool isSwapAX;<br>};<br>  •单行读取功能相关参数，说明见表5。<br>struct AippSingleLineParams {<br> bool isSingleLineCopy;<br>};<br>  •数据类型转换功能相关参数，说明见表6。<br>struct AippDataTypeConvParams {<br> uint8_t dtcMeanCh0{ 0 };<br> uint8_t dtcMeanCh1{ 0 };<br> uint8_t dtcMeanCh2{ 0 };<br> half dtcMinCh0{ 0 };<br> half dtcMinCh1{ 0 };<br> half dtcMinCh2{ 0 };<br> half dtcVarCh0{ 1.0 };<br> half dtcVarCh1{ 1.0 };<br> half dtcVarCh2{ 1.0 };<br> uint32_t dtcRoundMode{ 0 };<br>};<br>  •通道填充功能相关参数，说明见表7。<br>template &lt;typename T&gt;<br>struct AippChannelPaddingParams {<br> uint32_t cPaddingMode;<br> T cPaddingValue;<br>};<br>  •色域转换功能相关参数，说明见表8。<br>struct AippColorSpaceConvParams {<br> bool isEnableCsc;<br> int16_t cscMatrixR0C0;<br> int16_t cscMatrixR0C1;<br> int16_t cscMatrixR0C2;<br> int16_t cscMatrixR1C0;<br> int16_t cscMatrixR1C1;<br> int16_t cscMatrixR1C2;<br> int16_t cscMatrixR2C0;<br> int16_t cscMatrixR2C1;<br> int16_t cscMatrixR2C2;<br> uint8_t cscBiasIn0;<br> uint8_t cscBiasIn1;<br> uint8_t cscBiasIn2;<br> uint8_t cscBiasOut0;<br> uint8_t cscBiasOut1;<br> uint8_t cscBiasOut2;<br>};</td></tr></tbody></table><p><strong>表3</strong> AippPaddingParams结构体内参数说明<span id="table8955841508"></span></p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>paddingMode</td><td>输入</td><td>padding的模式，取值范围[0, 3]，默认值为0。<br>0：常数填充模式，此模式仅支持左右填充。<br>1：行列拷贝模式。<br>2：块拷贝模式。<br>3：镜像块拷贝模式。</td></tr><tr><td>paddingValueCh0</td><td>输入</td><td>padding区域中channel0填充的数据，仅常数填充模式有效，数据类型为T，默认值为0。</td></tr><tr><td>paddingValueCh1</td><td>输入</td><td>padding区域中channel1填充的数据，仅常数填充模式有效，数据类型为T，默认值为0。</td></tr><tr><td>paddingValueCh2</td><td>输入</td><td>padding区域中channel2填充的数据，仅常数填充模式有效，数据类型为T，默认值为0。</td></tr><tr><td>paddingValueCh3</td><td>输入</td><td>padding区域中channel3填充的数据，仅常数填充模式有效，数据类型为T，默认值为0。</td></tr></tbody></table><p><strong>表4</strong> AippSwapParams结构体内参数说明<span id="table679014222918"></span></p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>isSwapRB</td><td>输入</td><td>对于RGB888、XRGB8888格式，是否交换R和B通道。默认值为false。</td></tr><tr><td>isSwapUV</td><td>输入</td><td>对于YUV420SP格式，是否交换U和V通道。默认值为false。</td></tr><tr><td>isSwapAX</td><td>输入</td><td>对于XRGB8888格式，是否将X通道后移，即XRGB→RGBX。默认值为false。</td></tr></tbody></table><p><strong>表5</strong> AippSingleLineParams结构体内参数说明<span id="table193501032193419"></span></p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>isSingleLineCopy</td><td>输入</td><td>是否开启单行读取模式。开启后，仅从源图片读取一行。默认值为false。</td></tr></tbody></table><p><strong>表6</strong> AippDataTypeConvParams结构体内参数说明<span id="table14611192613519"></span></p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dtcMeanCh0</td><td>输入</td><td>计算公式内的mean值，channel0，数据类型为uint8_t，默认值为0。</td></tr><tr><td>dtcMeanCh1</td><td>输入</td><td>计算公式内的mean值，channel1，数据类型为uint8_t，默认值为0。</td></tr><tr><td>dtcMeanCh2</td><td>输入</td><td>计算公式内的mean值，channel2，数据类型为uint8_t，默认值为0。</td></tr><tr><td>dtcMinCh0</td><td>输入</td><td>计算公式内的min值，channel0，数据类型为half，默认值为0。<br>Atlas 200I/500 A2 推理产品不支持配置该参数。</td></tr><tr><td>dtcMinCh1</td><td>输入</td><td>计算公式内的min值，channel1，数据类型为half，默认值为0。<br>Atlas 200I/500 A2 推理产品不支持配置该参数。</td></tr><tr><td>dtcMinCh2</td><td>输入</td><td>计算公式内的min值，channel2，数据类型为half，默认值为0。<br>Atlas 200I/500 A2 推理产品不支持配置该参数。</td></tr><tr><td>dtcVarCh0</td><td>输入</td><td>计算公式内的var值，channel0，数据类型为half，默认值为1.0。</td></tr><tr><td>dtcVarCh1</td><td>输入</td><td>计算公式内的var值，channel1，数据类型为half，默认值为1.0。</td></tr><tr><td>dtcVarCh2</td><td>输入</td><td>计算公式内的var值，channel2，数据类型为half，默认值为1.0。</td></tr><tr><td>dtcRoundMode</td><td>输入</td><td>控制dtc做数据类型转换的模式，数据类型为uint32_t，默认值为0。<br>0：四舍五入到最接近的整数值（C语言round）。<br>1：四舍五入到最接近的偶数（C语言rint）。</td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>参数dtcRoundMode，仅在Atlas 200I/500 A2 推理产品支持配置。</p></div><p><strong>表7</strong> AippChannelPaddingParams结构体内参数说明<span id="table163681812917"></span></p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>cPaddingMode</td><td>输入</td><td>channel padding的类型，取值范围为[0, 1]，默认值为0。<br>0：填充到32B。即输出数据类型U为int8_t、uint8_t时填充到32通道，为half时填充到16通道。<br>1：填充到4通道。</td></tr><tr><td>cPaddingValue</td><td>输入</td><td>channel padding填充的值，数据类型为T，默认值为0。</td></tr></tbody></table><p><strong>表8</strong> AippColorSpaceConvParams结构体内参数说明<span id="table7858175271018"></span></p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>isEnableCsc</td><td>输入</td><td>是否开启色域转换功能，默认值为false。</td></tr><tr><td>cscMatrixR0C0</td><td>输入</td><td>色域转换矩阵cscMatrix[0][0]。</td></tr><tr><td>cscMatrixR0C1</td><td>输入</td><td>色域转换矩阵cscMatrix[0][1]。</td></tr><tr><td>cscMatrixR0C2</td><td>输入</td><td>色域转换矩阵cscMatrix[0][2]。</td></tr><tr><td>cscMatrixR1C0</td><td>输入</td><td>色域转换矩阵cscMatrix[1][0]。</td></tr><tr><td>cscMatrixR1C1</td><td>输入</td><td>色域转换矩阵cscMatrix[1][1]。</td></tr><tr><td>cscMatrixR1C2</td><td>输入</td><td>色域转换矩阵cscMatrix[1][2]。</td></tr><tr><td>cscMatrixR2C0</td><td>输入</td><td>色域转换矩阵cscMatrix[2][0]。</td></tr><tr><td>cscMatrixR2C1</td><td>输入</td><td>色域转换矩阵cscMatrix[2][1]。</td></tr><tr><td>cscMatrixR2C2</td><td>输入</td><td>色域转换矩阵cscMatrix[2][2]。</td></tr><tr><td>cscBiasIn0</td><td>输入</td><td>RGB转YUV偏置cscBiasIn[0]。YUV转RGB时无效。</td></tr><tr><td>cscBiasIn1</td><td>输入</td><td>RGB转YUV偏置cscBiasIn[1]。YUV转RGB时无效。</td></tr><tr><td>cscBiasIn2</td><td>输入</td><td>RGB转YUV偏置cscBiasIn[2]。YUV转RGB时无效。</td></tr><tr><td>cscBiasOut0</td><td>输入</td><td>YUV转RGB偏置cscBiasOut0[0]。RGB转YUV时无效。</td></tr><tr><td>cscBiasOut1</td><td>输入</td><td>YUV转RGB偏置cscBiasOut1[1]。RGB转YUV时无效。</td></tr><tr><td>cscBiasOut2</td><td>输入</td><td>YUV转RGB偏置cscBiasOut2[2]。RGB转YUV时无效。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>src0、src1在Global Memory上的地址对齐要求如下：</p><p><span id="table9587253131611"></span></p></li></ul><table><thead><tr><th>图片格式</th><th>src0</th><th>src1</th></tr></thead><tbody><tr><td>YUV420SP</td><td>必须2Bytes对齐</td><td>必须2Bytes对齐</td></tr><tr><td>XRGB8888</td><td>必须4Bytes对齐</td><td>-</td></tr><tr><td>RGB888</td><td>无对齐要求</td><td>-</td></tr><tr><td>YUV400</td><td>无对齐要求</td><td>-</td></tr></tbody></table><ul><li>对于XRGB输入格式的数据，芯片会默认丢弃第四个通道的数据输出RGB格式的数据。如果X在channel0的场景下，X通道后移功能必须使能，将输入通道转换为RGBX；反之如果X在channel3的场景下，X通道后移功能必须不使能，以输出RGB格式的数据。</li></ul><div data-filter="310p"><h2 id="调用示例">调用示例<span id="section6461234123118"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>SetAippFunctions需与<a href="LoadImageToLocal.html">LoadImageToLocal</a>接口配合使用，完整调用示例（含搬运过程）请参考<a href="LoadImageToLocal.html#section22811728184217">LoadImageToLocal的调用示例</a>。</p></div></article></div>`,1)])])}const C=s(o,[["render",h]]);export{v as __pageData,C as default};
